import re

def node_by_title(doc, title):
    for node in doc["nodes"]:
        if node["title"] == title:
            return node
    return None

def children(doc, node):
    return [node_by_id(doc, child_id) for child_id in node.get("children", [])]

def node_by_id(doc, node_id):
    for node in doc["nodes"]:
        if node["node_id"] == node_id:
            return node
    return None

def scope_nodes(doc, scope_title):
    scope = node_by_title(doc, scope_title)
    if not scope:
        return []
    return children(doc, scope)

def table_rows(node):
    if node["kind"] != "table":
        return []
    cols = node["table"]["columns"]
    return [(i, {cols[j]: row[j] for j in range(len(cols))}) 
            for i, row in enumerate(node["table"]["rows"])]

def entities(doc, scope):
    entities_list = []
    scope_nodes_list = scope_nodes(doc, scope)

    # Machines
    machines_node = next((n for n in scope_nodes_list if "Machines" in n["title"]), None)
    if machines_node:
        for row_idx, row in table_rows(machines_node):
            m_id = row["machine"]
            desc = f"Machine {m_id} (CPU: {row['CPU']}, memory: {row['memory']})"
            entities_list.append({"id": m_id, "description": desc})

    # Tasks
    task_log_node = next((n for n in scope_nodes_list if "Task log" in n["title"]), None)
    if task_log_node:
        tasks_seen = set()
        for row_idx, row in table_rows(task_log_node):
            t_id = row["task"]
            if t_id not in tasks_seen:
                desc = f"Task {t_id} (Job: {row['job']}, Priority: {row['priority']}, CPU: {row['CPU']}, memory: {row['memory']}, Run time: {row['run time']})"
                entities_list.append({"id": t_id, "description": desc})
                tasks_seen.add(t_id)

    return entities_list

def recorded_end(doc, scope):
    return 1200.0

def inputs(doc, scope):
    inputs_list = []
    scope_nodes_list = scope_nodes(doc, scope)

    # Machine Configs
    machines_node = next((n for n in scope_nodes_list if "Machines" in n["title"]), None)
    if machines_node:
        for row_idx, row in table_rows(machines_node):
            m_id = row["machine"]
            fails_at = float(row["fails at"]) if row["fails at"] != "-" else None
            returns_at = float(row["returns at"]) if row["returns at"] != "-" else None
            inputs_list.append({
                "id": f"input_machine_{m_id}",
                "time": 0.0,
                "kind": "machine_config",
                "entities": [m_id],
                "fields": {
                    "CPU": int(row["CPU"]),
                    "memory": int(row["memory"]),
                    "fails_at": fails_at,
                    "returns_at": returns_at
                },
                "src": [machines_node["node_id"], row_idx]
            })

    # Task Submissions
    task_log_node = next((n for n in scope_nodes_list if "Task log" in n["title"]), None)
    if task_log_node:
        for row_idx, row in table_rows(task_log_node):
            if row["event"] == "submit":
                t_id = row["task"]
                inputs_list.append({
                    "id": f"input_submit_{t_id}",
                    "time": float(row["time"]),
                    "kind": "task_submission",
                    "entities": [t_id],
                    "fields": {
                        "job": row["job"],
                        "priority": int(row["priority"]),
                        "CPU": int(row["CPU"]),
                        "memory": int(row["memory"]),
                        "run_time": int(row["run time"])
                    },
                    "src": [task_log_node["node_id"], row_idx]
                })

    return inputs_list

def outcomes(doc, scope):
    outcomes_list = []
    scope_nodes_list = scope_nodes(doc, scope)

    # Task events from log
    task_log_node = next((n for n in scope_nodes_list if "Task log" in n["title"]), None)
    if task_log_node:
        for row_idx, row in table_rows(task_log_node):
            event = row["event"]
            if event in ["start", "finish", "evict", "fail"]:
                t_id = row["task"]
                m_id = row["machine"] if row["machine"] != "-" else None
                ents = [t_id] if m_id is None else [t_id, m_id]
                outcomes_list.append({
                    "time": float(row["time"]),
                    "kind": f"task_{event}",
                    "entities": ents,
                    "value": None,
                    "src": [task_log_node["node_id"], row_idx]
                })

    # Machine events from Events list
    events_node = next((n for n in scope_nodes_list if "Events" in n["title"]), None)
    if events_node:
        for line_idx, line in enumerate(events_node.get("lines", [])):
            # Machine fail/return
            m_fail = re.search(r"Time (\d+): machine (M\d+) failed", line)
            if m_fail:
                outcomes_list.append({
                    "time": float(m_fail.group(1)),
                    "kind": "machine_fail",
                    "entities": [m_fail.group(2)],
                    "value": None,
                    "src": [events_node["node_id"], line_idx]
                })
            m_ret = re.search(r"Time (\d+): machine (M\d+) returned", line)
            if m_ret:
                outcomes_list.append({
                    "time": float(m_ret.group(1)),
                    "kind": "machine_return",
                    "entities": [m_ret.group(2)],
                    "value": None,
                    "src": [events_node["node_id"], line_idx]
                })

    # Queue at window end
    # Running tasks
    running_node = next((n for n in scope_nodes_list if "Queue at window end: Tasks running" in n["title"]), None)
    if running_node:
        for row_idx, row in table_rows(running_node):
            outcomes_list.append({
                "time": 1200.0,
                "kind": "final_state_running",
                "entities": [row["task"], row["machine"]],
                "value": float(row["remaining"]),
                "src": [running_node["node_id"], row_idx]
            })

    # Waiting tasks
    waiting_node = next((n for n in scope_nodes_list if "Queue at window end: Tasks waiting" in n["title"]), None)
    if waiting_node:
        for row_idx, row in table_rows(waiting_node):
            outcomes_list.append({
                "time": 1200.0,
                "kind": "final_state_waiting",
                "entities": [row["task"]],
                "value": None,
                "src": [waiting_node["node_id"], row_idx]
            })

    return outcomes_list

