def safe_float(val):
    if val is None or val == '-':
        return None
    try:
        return float(val)
    except (ValueError, TypeError):
        return None

def entities(doc, scope):
    ents = []
    seen = set()
    nodes = scope_nodes(doc, scope)

    # Machines
    m_node = next((n for n in nodes if n["kind"] == "table" and "Machines" in n["title"]), None)
    if m_node:
        for _, row in table_rows(m_node):
            mid = row["machine"]
            if mid not in seen:
                ents.append({"id": mid, "description": f"Machine {mid}"})
                seen.add(mid)

    # Tasks and Jobs
    t_node = next((n for n in nodes if n["kind"] == "table" and "Task log" in n["title"]), None)
    if t_node:
        for _, row in table_rows(t_node):
            tid = row["task"]
            if tid not in seen:
                ents.append({"id": tid, "description": f"Task {tid}"})
                seen.add(tid)
            jid = row["job"]
            if jid not in seen:
                ents.append({"id": jid, "description": f"Job {jid}"})
                seen.add(jid)

    # Queue end tasks
    for n in nodes:
        if "Queue at window end" in n["title"] and n["kind"] == "table":
            for _, row in table_rows(n):
                tid = row.get("task")
                if tid and tid not in seen:
                    ents.append({"id": tid, "description": f"Task {tid}"})
                    seen.add(tid)
    return ents

